export function init(selector, options) {
    
    let obj= $(selector).fdatepicker(options);
    obj.on('show',function(e){
        // console.log('show',e);
        DotNet.invokeMethodAsync("BulmaRazor","JSCallback",e.currentTarget.id,"show");
    }).on('hide',function(e){
        // console.log('hide',e);
        DotNet.invokeMethodAsync("BulmaRazor","JSCallback",e.currentTarget.id,"hide");
    }).on('changeDate',function(e){

        var dict={date:e.currentTarget.value};
        // console.log(dict);
        DotNet.invokeMethodAsync("BulmaRazor","JSCallbackWithParams",e.currentTarget.id,"changeDate",dict);
    });
    return obj;
}

export function show(selector) {
    $(selector).fdatepicker('show');
}
export function hide(selector) {
    $(selector).fdatepicker('hide');
}
